				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\rm A}_{ij}=\left\{\begin{array}{ll}\text{ max}(\mathrm{PMI}\left(i,j\right), 0)& i, j \text{are amino acid}, i\ne j\\ \text{ TF}-\mathrm{IDF}\left(i,j\right) & i \text{is sequence}, j\text{ is amino acid}\\ 1& i=j\\ 0& \mathrm{otherwise}\end{array}\right.$$\end{document}Aij=max(PMIi,j,0)i,jare amino acid,i≠jTF-IDFi,jiis sequence,jis amino acid1i=j0otherwise

