				\begin{document}$$\left\{\begin{array}{c}Accuracy=\frac{TP+TN}{TP+TN+FP+FN}\\ Sensitivity=Recall=\frac{TP}{TP+FN}\\ Specificity=\frac{TN}{TN+FP}\\ MCC=\frac{TP\times TN-FP\times FN}{\sqrt{\left(TP+FP\right)\left(TP+FN\right)\left(TN+FN\right)\left(TN+FP\right)}}\\ AUC: Area\ under\ the\ ROC\ Curve\end{array}\right.$$\end{document}{Accuracy=TP+TNTP+TN+FP+FNwhere TP, TN, FP, and FN represent the number of True Positives, True Negatives, False Positives, and False Negatives, respectively[54–58].
